func booksPageURL(q, format string, libID int64, page int) string {
	v := url.Values{}
	if q != "" {
		v.Set("q", q)
	}
	if format != "" {
		v.Set("format", format)
	}
	if libID > 0 {
		v.Set("library", fmt.Sprintf("%d", libID))
	}
	if page > 1 {
		v.Set("page", fmt.Sprintf("%d", page))
	}
	qs := v.Encode()
	if qs == "" {
		return "/books"
	}
	return "/books?" + qs
}

func progressData(p *models.Progress) map[string]any {
	if p == nil {
		return map[string]any{"percent": float64(0), "position": map[string]any{}, "status": "unread"}
	}
	var pos any = map[string]any{}
	if len(p.Position) > 0 {
		if err := json.Unmarshal(p.Position, &pos); err != nil {
			pos = map[string]any{}
		}
	}
	return map[string]any{
		"percent":  p.Percent,
		"position": pos,
		"status":   p.Status,
	}
}

func annotationsExportHref(f models.AnnotationFilter) string {
	parts := []string{}
	if f.BookID > 0 {
		parts = append(parts, fmt.Sprintf("book=%d", f.BookID))
	}
	if f.LibraryID > 0 {
		parts = append(parts, fmt.Sprintf("library=%d", f.LibraryID))
	}
	if f.Format != "" {
		parts = append(parts, "format="+f.Format)
	}
	if f.Kind != "" {
		parts = append(parts, "kind="+f.Kind)
	}
	if f.Color != "" {
		parts = append(parts, "color="+f.Color)
	}
	if f.Tag != "" {
		parts = append(parts, "tag="+f.Tag)
	}
	if f.Query != "" {
		parts = append(parts, "q="+f.Query)
	}
	if len(parts) == 0 {
		return "/annotations/export"
	}
	return "/annotations/export?" + strings.Join(parts, "&")
}

